 static AnimatorController Animations(){var c=AnimatorController.CreateAnimatorControllerAtPath(F+"/Animation/PrototypeLocomotion.controller");c.AddParameter("Speed",AnimatorControllerParameterType.Float);c.AddParameter("Running",AnimatorControllerParameterType.Bool);var tree=new BlendTree{name="IdleWalkRun",blendParameter="Speed",useAutomaticThresholds=false};AssetDatabase.AddObjectToAsset(tree,c);
  for(int mode=0;mode<3;mode++){var clip=new AnimationClip{name=new[]{"Idle","Walk","Run"}[mode],frameRate=30};float duration=mode==2?.55f:.9f;foreach(string limb in new[]{"LeftArm","RightArm","LeftLeg","RightLeg"}){float sign=limb=="LeftArm"||limb=="RightLeg"?1:-1;float v=mode==0?0:mode==1?28:44;var curve=new AnimationCurve(new Keyframe(0,v*sign),new Keyframe(duration*.5f,-v*sign),new Keyframe(duration,v*sign));clip.SetCurve(limb,typeof(Transform),"localEulerAnglesRaw.x",curve);}var settings=AnimationUtility.GetAnimationClipSettings(clip);settings.loopTime=true;AnimationUtility.SetAnimationClipSettings(clip,settings);AssetDatabase.CreateAsset(clip,F+"/Animation/"+clip.name+".anim");tree.AddChild(clip,mode==0?0:mode==1?2.2f:3.8f);}
  var state=c.layers[0].stateMachine.AddState("Locomotion");state.motion=tree;c.layers[0].stateMachine.defaultState=state;return c;
