 static void Dust(Transform root){var go=Group("BoundedLocalDust_NoVolumetrics",root).gameObject;go.layer=8;var ps=go.AddComponent<ParticleSystem>();ps.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);var main=ps.main;main.startLifetime=3;main.startSpeed=.7f;main.startSize=new ParticleSystem.MinMaxCurve(.06f,.22f);main.startColor=new Color(.63f,.42f,.26f,.18f);main.maxParticles=240;main.simulationSpace=ParticleSystemSimulationSpace.World;var shape=ps.shape;shape.shapeType=ParticleSystemShapeType.Box;shape.scale=new Vector3(16,7,16);var velocity=ps.velocityOverLifetime;velocity.enabled=true;velocity.x=-1.8f;velocity.y=-.1f;var mat=Mat("Dust_Particle",new Color(.63f,.42f,.26f,.18f),"Universal Render Pipeline/Particles/Unlit");mat.SetFloat("_Surface",1);mat.SetFloat("_Blend",0);mat.SetFloat("_SrcBlend",(float)BlendMode.SrcAlpha);mat.SetFloat("_DstBlend",(float)BlendMode.OneMinusSrcAlpha);mat.SetFloat("_ZWrite",0);mat.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");mat.renderQueue=3000;ps.GetComponent<ParticleSystemRenderer>().sharedMaterial=mat;p.dust=ps;p.dustMaterial=mat;}
 static void Hud(Transform root){var go=Group("MissionHUD_Prototype",root).gameObject;var canvas=go.AddComponent<Canvas>();canvas.renderMode=RenderMode.ScreenSpaceOverlay;var scaler=go.AddComponent<CanvasScaler>();scaler.uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;scaler.referenceResolution=new Vector2(1280,720);scaler.matchWidthOrHeight=.5f;p.hud=canvas;
