  var label=Group("Readouts",panel.transform).gameObject;var tr=label.AddComponent<RectTransform>();tr.anchorMin=Vector2.zero;tr.anchorMax=Vector2.one;tr.offsetMin=new Vector2(14,10);tr.offsetMax=new Vector2(-10,-10);var text=label.AddComponent<Text>();text.font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");text.fontSize=19;text.color=new Color(.83f,.91f,.93f);text.raycastTarget=false;text.horizontalOverflow=HorizontalWrapMode.Wrap;text.verticalOverflow=VerticalWrapMode.Overflow;p.status=text;}
 public static void BatchValidate(){EditorSceneManager.OpenScene(Scene);SessionState.SetBool("Stage08B.BatchRun",true);EditorApplication.isPlaying=true;}
 static void BeginTest(){p=UnityEngine.Object.FindAnyObjectByType<MarsPrototype>();TouchChecks.Run(p);if(!p)throw new Exception("Stage08B component absent");var logs=typeof(EditorApplication).Assembly.GetType("UnityEditor.LogEntries");var prior=new object[]{0,0,0};logs?.GetMethod("GetCounts",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.Public)?.Invoke(null,prior);File.WriteAllText(Out+"/Evidence/Resolved_Pretest_Console_Counts.txt",$"errors={prior[0]} warnings={prior[1]} logs={prior[2]} — resolved authoring history retained in Editor log\n");logs?.GetMethod("Clear",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.Public)?.Invoke(null,null);qaKeyboard=InputSystem.AddDevice<Keyboard>();InputSystem.QueueStateEvent(qaKeyboard,new KeyboardState(Key.W));p.testControl=true;p.testRun=false;qa=true;step=0;start=p.elapsed;last=Time.realtimeSinceStartup;results.Clear();frames.Clear();before=p.astronaut.transform.position;p.testMove=Vector2.up;}
 static void Check(string n,bool passed){results.Add(n+": "+(passed?"PASS":"FAIL"));}
 static void TestTick(){if(!EditorApplication.isPlaying||!p){qa=false;return;}float now=Time.realtimeSinceStartup;if(Time.frameCount!=frame){frame=Time.frameCount;frames.Add(Time.unscaledDeltaTime);}float age=p.elapsed-start;
  if(step==0&&age>3){Check("walk displacement",Vector3.Distance(before,p.astronaut.transform.position)>3);Check("walk speed",p.speed>1&&p.speed<=2.3f);Check("grounded",p.astronaut.isGrounded);Check("walk animator",p.animator.GetFloat("Speed")>1);Capture("01_Walk");before=p.astronaut.transform.position;p.testRun=true;InputSystem.QueueStateEvent(qaKeyboard,new KeyboardState(Key.W,Key.LeftShift));step++;}
  else if(step==1&&age>6){Check("run speed",p.speed>3&&p.speed<=4);Check("run displacement",Vector3.Distance(before,p.astronaut.transform.position)>7);InputSystem.QueueStateEvent(qaKeyboard,new KeyboardState());p.testControl=true;p.testMove=Vector2.zero;p.testLook=new Vector2(8,0);step++;}
  else if(step==2&&age>7){Check("camera yaw",p.yaw>1);p.testLook=Vector2.zero;p.testRun=false;File.WriteAllText(Out+"/Evidence/Walking_Provisional_Synthetic_Telemetry.json",p.BatchJson());p.ResetLocalSession();
   p.astronaut.enabled=false;p.astronaut.transform.position=p.rover.transform.position+p.rover.transform.right*3;p.astronaut.enabled=true;Physics.SyncTransforms();Check("enter rover",p.Interact()&&p.driving);p.testMove=Vector2.up;before=p.rover.transform.position;step++;}
  else if(step==3&&age>11){Check("rover acceleration",p.speed>2);Check("rover terrain travel",Vector3.Distance(before,p.rover.transform.position)>4);Check("rover grounded",p.rover.isGrounded);Check("exit while moving rejected",!p.Interact());Capture("02_Rover");p.testMove=new Vector2(1,1);before=p.rover.transform.eulerAngles;step++;}
  else if(step==4&&age>13){Check("rover steering",Mathf.Abs(Mathf.DeltaAngle(before.y,p.rover.transform.eulerAngles.y))>5);p.testBrake=true;step++;}
  else if(step==5&&age>15){Check("rover braking",Mathf.Abs(p.speed)<.2f);Check("exit rover",p.Interact()&&!p.driving);p.testMove=Vector2.zero;p.testBrake=false;p.SetWeather(1);step++;}
  else if(step==6&&age>17){Check("light dust",p.weather==1&&p.dust.particleCount>0);Capture("03_LightDust");p.SetWeather(2);step++;}
  else if(step==7&&age>20){Check("storm particles bounded",p.weather==2&&p.dust.particleCount>0&&p.dust.particleCount<=240);Check("storm visibility",RenderSettings.fogEndDistance<=50);Check("HUD resources",p.oxygen<100&&p.power<100&&p.status.text.Contains("DUST STORM"));Capture("04_Storm");p.SetWeather(0);step++;}
  else if(step==8&&age>22){Check("clear transition",p.weather==0&&RenderSettings.fogEndDistance>=250);Capture("05_Clear");File.WriteAllText(Out+"/Evidence/Scripted_Play_Mode_Tests.txt",string.Join("\n",results)+"\n");File.WriteAllText(Out+"/Evidence/Provisional_Synthetic_Telemetry.json",p.BatchJson());
   var log=typeof(EditorApplication).Assembly.GetType("UnityEditor.LogEntries");var args=new object[]{0,0,0};log?.GetMethod("GetCounts",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.Public)?.Invoke(null,args);File.WriteAllText(Out+"/Evidence/Console_Counts.txt",$"errors={args[0]} warnings={args[1]} logs={args[2]}\n");
   File.WriteAllText(Out+"/Evidence/Editor_Frame_Samples.csv","unscaled_frame_seconds\n"+string.Join("\n",frames.Select(f=>f.ToString(System.Globalization.CultureInfo.InvariantCulture)))+"\n");InputSystem.RemoveDevice(qaKeyboard);qaKeyboard=null;qa=false;p.testControl=false;Debug.Log("STAGE08B_TEST_COMPLETE");if(Application.isBatchMode)EditorApplication.Exit(results.Any(r=>r.EndsWith("FAIL"))?1:0);}
 }
 static void Capture(string name){if(p&&p.follow){ScreenCapture.CaptureScreenshot(Out+"/Screenshots/"+name+"_Game.png");var rt=new RenderTexture(1280,720,24);rt.Create();RenderPipeline.SubmitRenderRequest(p.follow,new UniversalRenderPipeline.SingleCameraRequest{destination=rt});var prior=RenderTexture.active;RenderTexture.active=rt;var t=new Texture2D(1280,720,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,1280,720),0,0);t.Apply();File.WriteAllBytes(Out+"/Screenshots/"+name+"_URP_NoHUD.png",t.EncodeToPNG());RenderTexture.active=prior;UnityEngine.Object.DestroyImmediate(t);rt.Release();UnityEngine.Object.DestroyImmediate(rt);}}
